\documentclass[11pt]{article}
\usepackage[margin=1in]{geometry}
\usepackage{amsmath,amssymb}
\title{Inexact Gradient Descent: A Residual Bound}\author{EAR Authored Reference Walkthrough}\date{}\begin{document}\maketitle
\begin{abstract}For step sizes up to 1/L, bounded gradient error gives an asymptotic residual bound of epsilon / mu. Constant bias can attain this bound.\end{abstract}
\section{Setting and theorem}Let $Q$ be symmetric positive definite, with $\mu I\preceq Q\preceq LI$. Choose $0<\eta<2/L$ and $q=\max\{|1-\eta\mu|,|1-\eta L|\}<1$. For $x_{k+1}=(I-\eta Q)x_k-\eta e_k$ and $\|e_k\|\le\epsilon_k$,
\[\|x_k\|\le q^k\|x_0\|+\eta\sum_{s=0}^{k-1}q^{k-1-s}\epsilon_s.\]
\section{Proof}Diagonalize Q in an orthonormal eigenbasis. The spectral norm of I-eta*Q is at most q. Applying the triangle inequality gives ||x[k+1]|| <= q||x[k]|| + eta*epsilon[k]. Induction unrolls this recurrence into the stated bound. For a uniformly bounded error, the geometric series is at most 1/(1-q). If eta <= 1/L, the endpoint factors are nonnegative and q=1-eta*mu.
\section{Corollary}If epsilon[s] <= epsilon, limsup ||x[k]|| <= eta*epsilon/(1-q). For eta <= 1/L, q=1-eta*mu and the bound becomes epsilon/mu.
\section{Boundary case}In one dimension, take Q=mu, x[0]=0 and e[k]=epsilon. Then x[k] = -(epsilon/mu)(1-(1-eta*mu)^k), so x[k] tends to -epsilon/mu instead of zero.
\section{Numerical check}We use $Q=\mathrm{diag}(1,10)$, $\eta=0.1$, $x_0=(1,1)$ and $e_k=(0.10,0)$. 81 saved states obey the bound. This numerical check is not a proof.
\section{Provenance and limitations}An authored reference task, not an EAR model episode or a new research result. Prepared review feedback led to explicit scope and the complete boundary argument. No conference acceptance or formal verification is claimed.
\begin{thebibliography}{1}\bibitem{boyd}S. Boyd and L. Vandenberghe. Convex Optimization. Cambridge University Press, 2004. Chapter 9.\end{thebibliography}\end{document}

